using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;
using UnityEditor;
namespace RebirthEntityStudio {
 [Serializable] public sealed class NativeAppearanceFile {public string path,sha256;}
 [Serializable] public sealed class NativeAppearanceStyle {public string key,gender,family,name,bundle,rendererName,meshName,data,dataHash,asset;public int vertices;}
 [Serializable] public sealed class NativeAppearanceCatalog {public int version;public string gameRoot,sourceHash;public NativeAppearanceStyle[] styles;public NativeAppearanceFile[] sources,outputs;}
 [Serializable] public sealed class NativeAppearanceHead {public float[] positions;public int[] triangles;public Vector3[] Points()=>Enumerable.Range(0,positions.Length/3).Select(i=>new Vector3(positions[i*3],positions[i*3+1],positions[i*3+2])).ToArray();}
 public static class RebirthNativeAppearanceLibrary {
  static NativeAppearanceCatalog catalog;static NativeHairColourCatalog colours;static string cache;
  static readonly Dictionary<string,NativeFittedVertices> fits=new Dictionary<string,NativeFittedVertices>();static readonly Dictionary<string,SkinnedMeshRenderer> renderers=new Dictionary<string,SkinnedMeshRenderer>();static readonly Dictionary<string,NativeAppearanceHead> heads=new Dictionary<string,NativeAppearanceHead>();static readonly HashSet<string> verified=new HashSet<string>();
  public static void Reload(){catalog=null;colours=null;cache=null;fits.Clear();renderers.Clear();heads.Clear();verified.Clear();NativeFacialSurfaceFit.Clear();RebirthNativeAuthoredHairBlend.Clear();NativeFacialRootAttachment.Clear();}
  public static bool Available=>File.Exists(Path.Combine(RebirthNativeAppearanceImport.Configuration().cacheDirectory??"","Catalog.json"));
  public static NativeAppearanceCatalog Catalog {get{Load();return catalog;}}
  public static NativeHairColourCatalog Colours {get{Load();return colours;}}
  static string SafePath(string root,string relative){string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string path=Path.GetFullPath(Path.Combine(prefix,relative));if(!path.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Appearance path leaves its source folder.");return path;}
  static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
  static void Verify(string path,string expected){if(verified.Contains(path))return;if(!File.Exists(path)||Hash(path)!=expected)throw new InvalidDataException("Native appearance source changed or is incomplete: "+Path.GetFileName(path)+". Import the current game library again.");verified.Add(path);}
  static void Load(){if(catalog!=null)return;var config=RebirthNativeAppearanceImport.Configuration();cache=config.cacheDirectory;if(string.IsNullOrEmpty(cache)||!File.Exists(Path.Combine(cache,"Catalog.json")))throw new FileNotFoundException("Import the installed-game appearance library first.");var next=JsonUtility.FromJson<NativeAppearanceCatalog>(File.ReadAllText(Path.Combine(cache,"Catalog.json")));if(next.version!=1||next.styles==null||next.outputs==null||next.sources==null)throw new InvalidDataException("Native appearance cache requires reimport with the current tool.");catalog=next;try{colours=Read<NativeHairColourCatalog>("Swatches.json");}catch{catalog=null;throw;}}
  public static T Read<T>(string file){Load();var record=catalog.outputs.SingleOrDefault(r=>r.path==file);if(record==null)throw new InvalidDataException("Missing native appearance cache record: "+file);var path=SafePath(cache,file);Verify(path,record.sha256);return JsonUtility.FromJson<T>(File.ReadAllText(path));}
  public static NativeAppearanceHead Head(string gender){Load();NativeAppearanceHead data;if(!heads.TryGetValue(gender,out data))heads[gender]=data=Read<NativeAppearanceHead>("Head_"+gender+".json");return data;}
  public static NativeAppearanceStyle Style(string key){Load();return catalog.styles.SingleOrDefault(s=>s.key==key)??throw new InvalidDataException("The saved native style is unavailable: "+key);}
  public static void ValidateSource(FaceNativeAppearanceSettings settings){Load();settings.Validate();if(!string.IsNullOrEmpty(settings.sourceHash)&&settings.sourceHash!=catalog.sourceHash)throw new InvalidDataException("This recipe requires its original native appearance source revision. Import that game revision or explicitly choose the current library.");}
  static AssetBundle LoadBundle(string relative,string expectedAsset){Load();string gamePath="Data/Addressables/Standalone/"+relative;var record=catalog.sources.SingleOrDefault(r=>r.path==gamePath);if(record==null)throw new InvalidDataException("Unrecorded native bundle: "+relative);string path=SafePath(catalog.gameRoot,gamePath);Verify(path,record.sha256);foreach(var existing in AssetBundle.GetAllLoadedAssetBundles())if(existing.GetAllAssetNames().Contains(expectedAsset,StringComparer.OrdinalIgnoreCase))return existing;var bundle=AssetBundle.LoadFromFile(path);if(bundle==null)throw new IOException("Native bundle could not be loaded: "+relative);return bundle;}
  public static SkinnedMeshRenderer Source(NativeAppearanceStyle style){SkinnedMeshRenderer source;if(renderers.TryGetValue(style.key,out source)&&source!=null)return source;var shaderFile=catalog.sources.Single(r=>r.path=="Data/Addressables/Standalone/shaders_assets_all.bundle");Verify(SafePath(catalog.gameRoot,shaderFile.path),shaderFile.sha256);RebirthNativeShaderLibrary.Get("Game/SDCS/Hair",Path.Combine(catalog.gameRoot,"Data","Addressables","Standalone"));LoadBundle("player_assets_entities/player/common.bundle","Assets/AssetBundles/Player/Common/HairColorSwatches/01 Blond.asset");var bundle=LoadBundle(style.bundle,style.asset);source=bundle.LoadAllAssets<GameObject>().SelectMany(p=>p.GetComponentsInChildren<SkinnedMeshRenderer>(true)).FirstOrDefault(r=>r.name==style.rendererName&&r.sharedMesh!=null&&r.sharedMesh.name==style.meshName&&r.sharedMesh.vertexCount==style.vertices);if(source==null)throw new InvalidDataException("The native style renderer does not match the imported data: "+style.key);renderers[style.key]=source;return source;}
  public static NativeFittedVertices Fit(NativeAppearanceStyle style){NativeFittedVertices data;if(!fits.TryGetValue(style.key,out data))fits[style.key]=data=Read<NativeFittedVertices>(style.data);return data;}
  static float Quantile(float[] values,float t){Array.Sort(values);float p=(values.Length-1)*t;int i=(int)p;return Mathf.Lerp(values[i],values[Mathf.Min(i+1,values.Length-1)],p-i);}
  public static NativeCrownCage Crown(NativeAppearanceHead source,Mesh target){var a=source.Points();var all=target.vertices;var b=target.GetTriangles(0).Distinct().Select(i=>all[i]).ToArray();float at=a.Max(p=>p.y),bt=b.Max(p=>p.y);var rings=new List<NativeCrownRing>();foreach(float drop in new[]{.02f,.04f,.06f,.08f,.10f}){var aa=a.Where(p=>Mathf.Abs(p.y-(at-drop))<.012f).ToArray();var bb=b.Where(p=>Mathf.Abs(p.y-(bt-drop))<.012f).ToArray();if(aa.Length<8||bb.Length<8)throw new InvalidDataException("Insufficient scalp surface for native fitting.");float ax0=Quantile(aa.Select(p=>p.x).ToArray(),.01f),ax1=Quantile(aa.Select(p=>p.x).ToArray(),.99f),az0=Quantile(aa.Select(p=>p.z).ToArray(),.01f),az1=Quantile(aa.Select(p=>p.z).ToArray(),.99f);float bx0=Quantile(bb.Select(p=>p.x).ToArray(),.01f),bx1=Quantile(bb.Select(p=>p.x).ToArray(),.99f),bz0=Quantile(bb.Select(p=>p.z).ToArray(),.01f),bz1=Quantile(bb.Select(p=>p.z).ToArray(),.99f);float sx=(bx1-bx0)/(ax1-ax0),sz=(bz1-bz0)/(az1-az0);if(sx<.4f||sx>1.8f||sz<.4f||sz>1.8f)throw new InvalidDataException("Head proportions exceed the supported native crown fit.");rings.Add(new NativeCrownRing{drop=drop,sourceX=(ax0+ax1)*.5f,sourceZ=(az0+az1)*.5f,targetX=(bx0+bx1)*.5f,targetZ=(bz0+bz1)*.5f,scaleX=sx,scaleZ=sz});}return new NativeCrownCage{sourceTop=at,targetTop=bt,rings=rings.ToArray()};}
  public static Mesh Hair(Mesh target,FaceNativeAppearanceSettings settings){ValidateSource(settings);if(string.IsNullOrEmpty(settings.hairKey))return new Mesh{name="No native hair"};var style=Style(settings.hairKey);if(style.family!="hair")throw new InvalidDataException("Selected style is not head hair.");var mesh=RebirthNativeAuthoredHairBlend.Active(settings)?RebirthNativeAuthoredHairBlend.Build(target,style,settings):RebirthNativeHairFit.Build(Source(style).sharedMesh,Fit(style),Crown(Head(style.gender),target));RebirthNativeHairFit.AdjustSize(mesh,target,settings.hairVolume,settings.hairSize,settings.hairWidth,settings.hairDepth);RebirthNativeHairFit.AdjustLength(mesh,target,settings.hairLength);return mesh;}
  static Material HairMaterial(Material original,NativeAppearanceStyle style,FaceNativeAppearanceSettings settings){
   bool separate=style.family!="hair"&&!settings.facialMatchHair;string colour=separate?settings.facialColourName:settings.colourName;var swatch=colours.swatches.SingleOrDefault(s=>s.name==colour);if(swatch==null)throw new InvalidDataException("Missing native hair colour: "+colour);
   var material=RebirthNativeHairFit.Colour(original,swatch);if(separate?settings.facialCustomTint:settings.customTint)material.SetColor("_Tint1",separate?settings.facialTint:settings.tint);if(!(separate?settings.facialPreserveNativeFinish:settings.preserveNativeFinish))RebirthNativeHairFit.Finish(material,separate?settings.facialShine:settings.shine,separate?settings.facialIdVariation:settings.idVariation,separate?settings.facialRootDarkening:settings.rootDarkening);if(!(separate?settings.facialPreserveNativeFinish:settings.preserveNativeFinish)&&(separate?settings.facialOverrideEnvironmentResponse:settings.overrideEnvironmentResponse))material.SetFloat("_Metallic",separate?settings.facialEnvironmentResponse:settings.environmentResponse);if(!(separate?settings.facialPreserveNativeFinish:settings.preserveNativeFinish)&&(separate?settings.facialOverrideSmoothness:settings.overrideSmoothness))material.SetFloat("_SmoothnessMultiplier",separate?settings.facialSmoothness:settings.smoothness);RebirthHairCondition.Apply(material,style.family=="hair"?settings.hairCondition:settings.facialCondition);material.hideFlags=HideFlags.HideAndDontSave;return material;
  }
  public static Material Material(string key,FaceNativeAppearanceSettings settings){ValidateSource(settings);var style=Style(key);var original=Source(style).sharedMaterials.FirstOrDefault(m=>m!=null&&m.shader!=null&&m.shader.name=="Game/SDCS/Hair");if(original==null)throw new InvalidDataException("Native style has no supported hair material: "+key);return HairMaterial(original,style,settings);}
  public static Material[] Materials(string key,FaceNativeAppearanceSettings settings){
   ValidateSource(settings);var style=Style(key);var source=Source(style);var originals=source.sharedMaterials;if(originals.Length!=source.sharedMesh.subMeshCount)throw new InvalidDataException("Native material/submesh layout is unsupported: "+key);var result=new Material[originals.Length];
   try{for(int i=0;i<result.Length;i++){var original=originals[i];if(original==null||original.shader==null)throw new InvalidDataException("Native material is missing: "+key);if(original.shader.name=="Game/SDCS/Hair")result[i]=HairMaterial(original,style,settings);else if(original.shader.name=="Standard")result[i]=new Material(original){hideFlags=HideFlags.HideAndDontSave};else throw new InvalidDataException("Unsupported native accessory shader: "+original.shader.name);}return result;}
   catch{foreach(var m in result)if(m!=null)UnityEngine.Object.DestroyImmediate(m);throw;}
  }
  public static string[] FacialKeys(FaceNativeAppearanceSettings s)=>new[]{s.beardKey,s.moustacheKey,s.sideburnKey}.Where(k=>!string.IsNullOrEmpty(k)).ToArray();
  public static FacialHairResult Facial(Mesh target,FaceNativeAppearanceSettings settings){
   ValidateSource(settings);if(string.IsNullOrEmpty(settings.facialAttachmentGuid)&&((!string.IsNullOrEmpty(settings.beardKey)&&(settings.beardLength!=0||settings.beardFullness!=0))||(!string.IsNullOrEmpty(settings.moustacheKey)&&(settings.moustacheLength!=0||settings.moustacheFullness!=0))||(!string.IsNullOrEmpty(settings.sideburnKey)&&(settings.sideburnLength!=0||settings.sideburnFullness!=0))))throw new InvalidDataException("Fit facial hair to this head before using shape controls.");var result=new FacialHairResult();var parts=new List<Mesh>();var materials=new List<Material>();var combined=new List<CombineInstance>();
   try{foreach(string key in FacialKeys(settings)){var style=Style(key);if(style.family=="hair")throw new InvalidDataException("Head hair cannot occupy a facial-hair slot.");var source=Source(style).sharedMesh;var fitted=string.IsNullOrEmpty(settings.facialAttachmentGuid)?NativeFacialSurfaceFit.Fit(Head(style.gender),target,Fit(style),source):NativeFacialRootAttachment.Apply(target,NativeFacialRootAttachment.Load(settings.facialAttachmentGuid),catalog.sourceHash,key,style.family=="beard"?settings.beardLength:style.family=="moustache"?settings.moustacheLength:settings.sideburnLength,style.family=="beard"?settings.beardFullness:style.family=="moustache"?settings.moustacheFullness:settings.sideburnFullness);var part=RebirthNativeHairFit.BuildSurfaceFit(source,fitted);parts.Add(part);materials.AddRange(Materials(key,settings));for(int sub=0;sub<part.subMeshCount;sub++)combined.Add(new CombineInstance{mesh=part,subMeshIndex=sub,transform=Matrix4x4.identity});}
    if(parts.Count>0){result.mesh=new Mesh{name="Native-derived facial hair",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};result.mesh.CombineMeshes(combined.ToArray(),false,false);result.materials=materials.ToArray();}return result;}
   catch{foreach(var m in materials)UnityEngine.Object.DestroyImmediate(m);result.materials=new Material[0];result.Dispose();throw;}
   finally{foreach(var p in parts)UnityEngine.Object.DestroyImmediate(p);}
  }
 }
}







